import os
import torch


class Config:
    """
    Configuration for Time-Shortcut Cascaded Residual Network (TSCR-Net).
    Centralizes all constants, paths, and hyperparameters.
    """

    # -------------------------------------------------------------------------
    # File System Paths
    # -------------------------------------------------------------------------
    INPUT_DIR = "./input"
    METADATA_DIR = "./metadata"

    # Specific metadata paths generated by the metadata script
    TRAIN_META_PATH = os.path.join(METADATA_DIR, "train.csv")
    VAL_META_PATH = os.path.join(METADATA_DIR, "val.csv")
    TEST_META_PATH = os.path.join(METADATA_DIR, "test.csv")

    # Working directory for Idea 20
    WORKING_DIR = "./working/idea_20"
    CACHE_DIR = os.path.join(WORKING_DIR, "cache")
    CHECKPOINT_DIR = os.path.join(WORKING_DIR, "checkpoints")
    SUBMISSION_DIR = "./submission"
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")

    # Ensure working directories exist
    os.makedirs(CACHE_DIR, exist_ok=True)
    os.makedirs(CHECKPOINT_DIR, exist_ok=True)
    os.makedirs(SUBMISSION_DIR, exist_ok=True)

    # -------------------------------------------------------------------------
    # Reproducibility & Hardware
    # -------------------------------------------------------------------------
    SEED = 42
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"
    NUM_WORKERS = 4

    # Debugging control
    DEBUG = False
    DEBUG_SAMPLE_SIZE = 50  # Number of samples to use if DEBUG is True

    # -------------------------------------------------------------------------
    # Data Hyperparameters
    # -------------------------------------------------------------------------
    # Image Preprocessing
    IMAGE_SIZE = 260  # Native resolution for EfficientNet-B2
    NUM_SLICES = 3  # Anchor slice + 2 boundary slices
    IN_CHANNELS = 3  # Input channels for the backbone

    # Tabular Features
    # Note: 'Percent' is excluded to prevent leakage. 'Weeks' is handled dynamically.
    TABULAR_FEATURES = ["Age", "Sex", "SmokingStatus"]

    # Normalization Constants (Derived from EDA)
    # Target Variable: FVC
    TARGET_MEAN = 2654.6528
    TARGET_STD = 801.7017

    # Input Variable: Age
    AGE_MEAN = 67.5825
    AGE_STD = 6.6259

    # Feature Engineering
    TIME_SCALE = 0.01  # Scale relative weeks (t_rel) by 0.01

    # -------------------------------------------------------------------------
    # Model Architecture
    # -------------------------------------------------------------------------
    BACKBONE_NAME = "tf_efficientnet_b2_ns"
    PROJECTION_DIM = 64  # Dimension of image feature projection
    HIDDEN_DIM = 64  # Dimension of internal MLP layers (Stream A & B)

    # -------------------------------------------------------------------------
    # Training Hyperparameters
    # -------------------------------------------------------------------------
    BATCH_SIZE = 32  # Optimized for A100 40GB
    N_EPOCHS = 50  # Extended duration for uncertainty calibration

    # Differential Learning Rates
    LR_BACKBONE = 1e-4  # Lower LR for fine-tuning pre-trained weights
    LR_HEADS = 1e-3  # Higher LR for MLPs and Heads

    WEIGHT_DECAY = 1e-2
    T_MAX = 50  # Cosine Annealing duration

    # Loss & Metric
    SIGMA_EPSILON = 1e-6  # Stability term for softplus
    METRIC_CLIP_SIGMA = 70.0  # Metric clipping (applied during evaluation/submission)
    METRIC_MAX_ERR = 1000.0  # Metric error threshold
